const REDACTED = '***';
const CREDENTIAL_QUERY_KEYS = [
    'access_token',
    'api_key',
    'apikey',
    'auth',
    'job_token',
    'password',
    'private_token',
    'pwd',
    'secret',
    'token',
];
const MAX_HOST = 256;
const USERINFO = '(?:[^@/\\s]*@)+';
const SCHEME_USERINFO_PATTERN = new RegExp(`([a-z][a-z0-9+.-]{0,31}://)${USERINFO}`, 'gi');
const SCP_USERINFO_PATTERN = new RegExp(`(^|\\s)[^/@\\s:]+:${USERINFO}(?=[^\\s:]{1,${MAX_HOST}}:)`, 'g');
const CREDENTIAL_QUERY_PATTERN = new RegExp(`([?&])(${CREDENTIAL_QUERY_KEYS.join('|')})=[^&#\\s]*`, 'gi');
export const redactUrl = (value) => value
    .replace(SCHEME_USERINFO_PATTERN, `$1${REDACTED}@`)
    .replace(SCP_USERINFO_PATTERN, `$1${REDACTED}@`)
    .replace(CREDENTIAL_QUERY_PATTERN, `$1$2=${REDACTED}`);
export const redactErrorMessage = (error) => redactUrl(error instanceof Error ? error.message : String(error));
export const redactOptionsForLog = (options) => {
    const redacted = { ...options };
    if (typeof redacted.remote === 'string') {
        redacted.remote = redactUrl(redacted.remote);
    }
    if (typeof redacted.skillSourceUrl === 'string') {
        redacted.skillSourceUrl = redactUrl(redacted.skillSourceUrl);
    }
    return redacted;
};
